// Host is the host's side of the wire: one method per request a driver sends (host/*). Embed
// UnsupportedHost to refuse the ones a host does not serve; MemoryHost serves the few a local
// host needs.
type Host interface {
	// ConfigGet answers host/config.get.
	ConfigGet(ctx context.Context, params HostConfigGetParams) (HostConfigGetResult, error)
	// SecretsGet answers host/secrets.get.
	SecretsGet(ctx context.Context, params HostSecretParams) (NullableSecretValue, error)
	// SecretsSet answers host/secrets.set.
	SecretsSet(ctx context.Context, params HostSecretsSetParams) (VoidResult, error)
	// SecretsDelete answers host/secrets.delete.
	SecretsDelete(ctx context.Context, params HostSecretParams) (VoidResult, error)
	// ProcessSpawn answers host/process.spawn.
	ProcessSpawn(ctx context.Context, params HostProcessSpawnParams) (SpawnResult, error)
	// ProcessResolveExecutable answers host/process.resolveExecutable.
	ProcessResolveExecutable(ctx context.Context, params HostProcessResolveExecutableParams) (NullableStringResult, error)
	// AttachmentsResolve answers host/attachments.resolve.
	AttachmentsResolve(ctx context.Context, params HostAttachmentParams) (NullableAttachmentInfo, error)
	// AttachmentsExtractText answers host/attachments.extractText.
	AttachmentsExtractText(ctx context.Context, params HostAttachmentParams) (NullableStringResult, error)
	// CallbacksRegister answers host/callbacks.register.
	CallbacksRegister(ctx context.Context, params HostCallbacksRegisterParams) (CallbackRegistration, error)
	// HostToolsMcpServerFor answers host/hostTools.mcpServerFor.
	HostToolsMcpServerFor(ctx context.Context, params HostMcpServerForParams) (HostToolServer, error)
	// HostToolsCallDynamicTool answers host/hostTools.callDynamicTool.
	HostToolsCallDynamicTool(ctx context.Context, params HostCallDynamicToolParams) (DynamicToolResult, error)
	// BackgroundShouldRun answers host/background.shouldRun.
	BackgroundShouldRun(ctx context.Context, params HostBackgroundShouldRunParams) (BooleanResult, error)
	// CoordinationAcquire answers host/coordination.acquire.
	CoordinationAcquire(ctx context.Context, params HostCoordinationAcquireParams) (NullableLease, error)
	// CoordinationRelease answers host/coordination.release.
	CoordinationRelease(ctx context.Context, params HostCoordinationReleaseParams) (VoidResult, error)
	// DiagnosticsLog answers host/diagnostics.log.
	DiagnosticsLog(ctx context.Context, params HostDiagnosticsLogParams) (VoidResult, error)
	// TelemetryTrack answers host/telemetry.track.
	TelemetryTrack(ctx context.Context, params HostTelemetryTrackParams) (VoidResult, error)
	// IDsDerive answers host/ids.derive.
	IDsDerive(ctx context.Context, params HostIdsDeriveParams) (StringResult, error)
	// ProcessWrite answers host/process.write.
	ProcessWrite(ctx context.Context, params HostProcessWriteParams) (VoidResult, error)
	// ProcessCloseStdin answers host/process.closeStdin.
	ProcessCloseStdin(ctx context.Context, params HostProcessTarget) (VoidResult, error)
	// ProcessKill answers host/process.kill.
	ProcessKill(ctx context.Context, params HostProcessKillParams) (VoidResult, error)
}

// UnsupportedHost refuses every host request with unsupported. Embed it in a Host.
type UnsupportedHost struct{}

